package org.firecracking.firelabel.core;

import static org.junit.jupiter.api.Assertions.*;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;
import org.junit.jupiter.api.Test;

class StripPatternTest {

    /** Shared with the Rust codec's tests; generated by `cargo run --example gen_vectors` in core/. */
    private static final Path GOLDEN = Paths.get("..", "core", "testdata", "strip_vectors.txt");

    private static String bits(boolean[] row) {
        StringBuilder sb = new StringBuilder();
        for (boolean b : row) sb.append(b ? '1' : '0');
        return sb.toString();
    }

    private static boolean[] slice(boolean[] cells, int from, int to) {
        boolean[] out = new boolean[to - from];
        System.arraycopy(cells, from, out, 0, out.length);
        return out;
    }

    private static boolean[] bitsOf(int value, int width) {
        boolean[] out = new boolean[width];
        for (int i = 0; i < width; i++) out[i] = ((value >> (width - 1 - i)) & 1) == 1;
        return out;
    }

    // ---------- basics ----------

    @Test
    void matchesTheRustCodecGoldenVectors() throws IOException {
        List<String> lines = Files.readAllLines(GOLDEN, StandardCharsets.UTF_8);
        assertEquals(20, lines.size(), "5 widths x 4 (tick, id) pairs");
        for (String line : lines) {
            String[] p = line.split(" ");
            int width = Integer.parseInt(p[0]);
            int tick = Integer.parseInt(p[1], 16);
            int id = Integer.parseInt(p[2], 16);
            assertEquals(
                    p[3],
                    bits(StripPattern.row(width, tick, id)),
                    "width " + width + " tick " + p[1] + " id " + p[2]);
        }
    }

    @Test
    void geometryAt1080p720pAnd4k() {
        assertEquals(58, StripPattern.CELLS);
        assertEquals(8.0, StripPattern.cellSize(1920), 1e-9);
        assertArrayEquals(new int[] {464, 8}, StripPattern.stripSize(1920));
        assertArrayEquals(new int[] {309, 5}, StripPattern.stripSize(1280));
        assertArrayEquals(new int[] {928, 16}, StripPattern.stripSize(3840));
    }

    @Test
    void calibrationCellsAreWhiteThenBlack() {
        for (int[] p : new int[][] {{0, 0}, {1, 2}, {0xABCDEF, 0x123456}, {StripPattern.MAX_TICK, StripPattern.MAX_ID}}) {
            boolean[] cells = StripPattern.cells(p[0], p[1]);
            assertEquals(58, cells.length);
            assertTrue(cells[0], "cell 0 white");
            assertFalse(cells[1], "cell 1 black");
        }
    }

    @Test
    void cellsCarryTickThenIdThenCrc() {
        int tick = 0xABCDEF;
        int id = 0x123456;
        boolean[] cells = StripPattern.cells(tick, id);
        assertArrayEquals(bitsOf(tick, 24), slice(cells, 2, 26), "tick cells 2..25");
        assertArrayEquals(bitsOf(id, 24), slice(cells, 26, 50), "id cells 26..49");
        int crc = Crc8.crc8(new byte[] {(byte) 0xAB, (byte) 0xCD, (byte) 0xEF, 0x12, 0x34, 0x56});
        assertArrayEquals(bitsOf(crc, 8), slice(cells, 50, 58), "crc cells 50..57");
    }

    @Test
    void tickAndIdAreNotInterchangeable() {
        assertFalse(java.util.Arrays.equals(StripPattern.cells(1, 2), StripPattern.cells(2, 1)));
        assertFalse(java.util.Arrays.equals(StripPattern.cells(0x10, 0x20), StripPattern.cells(0x20, 0x10)));
    }

    @Test
    void lastCellEndsExactlyAtTheStripWidth() {
        for (int w : new int[] {854, 1280, 1920, 2560, 3840}) {
            assertEquals(StripPattern.stripSize(w)[0], StripPattern.cellRange(w, 57)[1], "width " + w);
            assertEquals(0, StripPattern.cellRange(w, 0)[0]);
            // cells tile the strip with no gaps
            for (int i = 1; i < StripPattern.CELLS; i++) {
                assertEquals(StripPattern.cellRange(w, i - 1)[1], StripPattern.cellRange(w, i)[0]);
            }
        }
    }

    @Test
    void wrapTickKeepsTheLow24Bits() {
        assertEquals(0, StripPattern.wrapTick(0L));
        assertEquals(5, StripPattern.wrapTick(5L));
        assertEquals(StripPattern.MAX_TICK, StripPattern.wrapTick((long) StripPattern.MAX_TICK));
        assertEquals(0, StripPattern.wrapTick(StripPattern.MAX_TICK + 1L));
        assertEquals(5, StripPattern.wrapTick(StripPattern.MAX_TICK + 6L));
        int big = StripPattern.wrapTick(Long.MAX_VALUE);
        assertTrue(big >= 0 && big <= StripPattern.MAX_TICK);
    }

    // ---------- failures ----------

    @Test
    void acceptsEdgeValuesAndRejectsOutOfRange() {
        assertDoesNotThrow(() -> StripPattern.cells(0, 0));
        assertDoesNotThrow(() -> StripPattern.cells(StripPattern.MAX_TICK, StripPattern.MAX_ID));
        assertThrows(IllegalArgumentException.class, () -> StripPattern.cells(-1, 0));
        assertThrows(IllegalArgumentException.class, () -> StripPattern.cells(StripPattern.MAX_TICK + 1, 0));
        assertThrows(IllegalArgumentException.class, () -> StripPattern.cells(0, -1));
        assertThrows(IllegalArgumentException.class, () -> StripPattern.cells(0, StripPattern.MAX_ID + 1));
        assertThrows(IllegalArgumentException.class, () -> StripPattern.row(1920, -1, 0));
        assertThrows(IllegalArgumentException.class, () -> StripPattern.row(1920, 0, StripPattern.MAX_ID + 1));
    }

    @Test
    void wrapTickRejectsNegativeTicks() {
        assertThrows(IllegalArgumentException.class, () -> StripPattern.wrapTick(-1L));
    }

    @Test
    void tooNarrowFramesHaveNoStrip() {
        assertNull(StripPattern.stripSize(479));
        assertNull(StripPattern.stripSize(0));
        assertNull(StripPattern.stripSize(-5));
        assertArrayEquals(new int[] {116, 2}, StripPattern.stripSize(480));
        assertThrows(IllegalArgumentException.class, () -> StripPattern.row(400, 1, 1));
        assertThrows(IllegalArgumentException.class, () -> StripPattern.cellRange(400, 0));
    }

    @Test
    void cellIndexOutOfRangeIsRejected() {
        assertThrows(IllegalArgumentException.class, () -> StripPattern.cellRange(1920, -1));
        assertThrows(IllegalArgumentException.class, () -> StripPattern.cellRange(1920, 58));
    }
}
